svg.script:

(function() {
  // Data dictionary for dynamic card update
  var cordData = {
    'all': {
      title: "As Três Cordas de Suspensão Uterina",
      origem: "• Ant: Púbis → Bexiga → Útero | Lat: Parede Lateral | Pos: Sacro",
      vetor: "• Tração tridimensional equilibrada (Anterior, Transversa e Posterior)",
      c1: "• Nível I de DeLancey (Suspensão Apical).",
      c2: "• Lig. Cardinal (Mackenrodt) é o principal suporte lateral do colo.",
      c3: "• Contém a Artéria Uterina cruzando por cima do Ureter!",
      t1: "A ausência do ligamento cardinal no corte sagital é ILUSÃO",
      t2: "DE PLANO. Ele existe e fixa o colo lateralmente!"
    },
    'ant': {
      title: "1. Ligamento Pubovesicouterino (Anterior)",
      origem: "• Da face posterior da Sínfise Púbica → Bexiga → Colo Uterino",
      vetor: "• Vetor Anterior [A] (Traciona a bacia anterior)",
      c1: "• Fixa o útero anteriorizadamente sobre a bexiga.",
      c2: "• Auxilia na manutenção do ângulo de anteversoflexão (AVF).",
      c3: "• Lesão isolada favorece retroversão e cistocele associada.",
      t1: "Vetor Anterior: Evita o deslizamento posterior do colo",
      t2: "e mantém o corpo uterino apoiado na bexiga."
    },
    'lat': {
      title: "2. Ligamento Cardinal / Mackenrodt (Lateral)",
      origem: "• Da parede pélvica lateral (fáscia do obturador) → Colo Uterino (Istmo)",
      vetor: "• Vetor Transverso Bilateral [R / L] (Múltiplos eixos laterais)",
      c1: "• É O PRINCIPAL LIGAMENTO DE SUSTENTAÇÃO APICAL DO ÚTERO!",
      c2: "• Por ser lateral, DESAPARECE NO CORTE SAGITAL MEDIANO.",
      c3: "• Ponto crítico na histerectomia: Ureter passa INFERIOR à artéria uterina.",
      t1: "⚠️ ARMADILHA DE PROVA: Não o veja no corte sagital,",
      t2: "mas saiba que ele é o pilar mais forte de suspensão apical!"
    },
    'pos': {
      title: "3. Ligamento Uterossacro (Posterior)",
      origem: "• Da face posterior do colo uterino / fórnice posterior → Vértebras S2-S4",
      vetor: "• Vetor Posterossuperior [P] (Traciona o colo para trás/cima)",
      c1: "• Mantém o colo tracionado para trás, mantendo a AVF do corpo.",
      c2: "• Alvo principal da cirurgia de Fixação no Lig. Uterossacro.",
      c3: "• Forma os limites laterais do Fundo de Saco de Douglas.",
      t1: "Vetor Posterior: Mantém o colo em direção ao sacro,",
      t2: "sendo fundamental na prevenção do prolapso de cúpula."
    },
    'sustentacao': {
      title: "Aparelho de Sustentação (Diafragma Pélvico)",
      origem: "• Músculo Levantador do Ânus + M. Cócceo + Fáscias Endopélvicas",
      vetor: "• Vetor Ascendente Verticamente de Baixo para Cima (O Chão)",
      c1: "• Não é corda! É o CHÃO neuromuscular onde os órgãos repousam.",
      c2: "• Em repouso, fecha o hiato urogenital contra o aumento da PAI.",
      c3: "• Se o assoalho falha, os ligamentos (cordas) sofrem estiramento.",
      t1: "Sustentação é o CHÃO. Suspensão são as CORDAS.",
      t2: "Sem chão firme, nenhuma corda segura a carga para sempre!"
    }
  };

  // Helper to update elements safely
  function setElementText(id, text) {
    var el = document.getElementById(id);
    if (el) el.textContent = text;
  }

  function highlightCord(cordId) {
    var antAxial = document.getElementById('a12p20h-axial-cord-ant');
    var latAxial = document.getElementById('a12p20h-axial-cord-lat');
    var posAxial = document.getElementById('a12p20h-axial-cord-pos');

    var antSag = document.getElementById('a12p20h-sag-cord-ant');
    var latSag = document.getElementById('a12p20h-sag-cord-lat');
    var posSag = document.getElementById('a12p20h-sag-cord-pos');

    var floorAxial = document.getElementById('a12p20h-axial-floor-grp');
    var floorSag = document.getElementById('a12p20h-sagittal-floor-grp');

    var allCords = [antAxial, latAxial, posAxial, antSag, latSag, posSag];

    // Reset styles
    allCords.forEach(function(c) {
      if (c) {
        c.classList.remove('a12p20h-dimmed');
        c.classList.remove('a12p20h-cord-active');
      }
    });
    if (floorAxial) floorAxial.classList.remove('a12p20h-dimmed');
    if (floorSag) floorSag.classList.remove('a12p20h-dimmed');

    if (cordId === 'all') {
      // Keep all bright
    } else if (cordId === 'ant') {
      [latAxial, posAxial, latSag, posSag].forEach(function(c) { if (c) c.classList.add('a12p20h-dimmed'); });
      if (antAxial) antAxial.classList.add('a12p20h-cord-active');
      if (antSag) antSag.classList.add('a12p20h-cord-active');
    } else if (cordId === 'lat') {
      [antAxial, posAxial, antSag, posSag].forEach(function(c) { if (c) c.classList.add('a12p20h-dimmed'); });
      if (latAxial) latAxial.classList.add('a12p20h-cord-active');
      if (latSag) latSag.classList.add('a12p20h-cord-active');
    } else if (cordId === 'pos') {
      [antAxial, latAxial, antSag, latSag].forEach(function(c) { if (c) c.classList.add('a12p20h-dimmed'); });
      if (posAxial) posAxial.classList.add('a12p20h-cord-active');
      if (posSag) posSag.classList.add('a12p20h-cord-active');
    } else if (cordId === 'sustentacao') {
      allCords.forEach(function(c) { if (c) c.classList.add('a12p20h-dimmed'); });
    }

    // Update Text Info Box
    var data = cordData[cordId] || cordData['all'];
    setElementText('a12p20h-info-title', data.title);
    setElementText('a12p20h-info-origem', data.origem);
    setElementText('a12p20h-info-vetor', data.vetor);
    setElementText('a12p20h-info-clinica1', data.c1);
    setElementText('a12p20h-info-clinica2', data.c2);
    setElementText('a12p20h-info-clinica3', data.c3);
    setElementText('a12p20h-info-takeaway1', data.t1);
    setElementText('a12p20h-info-takeaway2', data.t2);
  }

  function switchView(viewMode) {
    var panelAxial = document.getElementById('a12p20h-panel-axial');
    var panelSagittal = document.getElementById('a12p20h-panel-sagittal');
    var panelInfo = document.getElementById('a12p20h-panel-info');

    var tabDual = document.getElementById('a12p20h-tab-dual');
    var tabAxial = document.getElementById('a12p20h-tab-axial');
    var tabSagittal = document.getElementById('a12p20h-tab-sagittal');

    [tabDual, tabAxial, tabSagittal].forEach(function(t) {
      if (t) t.classList.remove('a12p20h-tab-active');
    });

    if (viewMode === 'dual') {
      if (tabDual) tabDual.classList.add('a12p20h-tab-active');
      if (panelAxial) { panelAxial.setAttribute('transform', 'translate(30, 0)'); panelAxial.style.display = 'block'; }
      if (panelSagittal) { panelSagittal.setAttribute('transform', 'translate(420, 0)'); panelSagittal.style.display = 'block'; }
      if (panelInfo) { panelInfo.setAttribute('transform', 'translate(810, 0)'); panelInfo.style.display = 'block'; }
    } else if (viewMode === 'axial') {
      if (tabAxial) tabAxial.classList.add('a12p20h-tab-active');
      if (panelAxial) { panelAxial.setAttribute('transform', 'translate(30, 0)'); panelAxial.style.display = 'block'; }
      if (panelSagittal) { panelSagittal.style.display = 'none'; }
      if (panelInfo) { panelInfo.setAttribute('transform', 'translate(420, 0)'); panelInfo.style.display = 'block'; }
    } else if (viewMode === 'sagittal') {
      if (tabSagittal) tabSagittal.classList.add('a12p20h-tab-active');
      if (panelAxial) { panelAxial.style.display = 'none'; }
      if (panelSagittal) { panelSagittal.setAttribute('transform', 'translate(30, 0)'); panelSagittal.style.display = 'block'; }
      if (panelInfo) { panelInfo.setAttribute('transform', 'translate(420, 0)'); panelInfo.style.display = 'block'; }
    }
  }

  // Event Binding
  document.addEventListener("DOMContentLoaded", function() {
    var selAll = document.getElementById('a12p20h-sel-all');
    var selAnt = document.getElementById('a12p20h-sel-ant');
    var selLat = document.getElementById('a12p20h-sel-lat');
    var selPos = document.getElementById('a12p20h-sel-pos');

    if (selAll) selAll.addEventListener('click', function() { highlightCord('all'); });
    if (selAnt) selAnt.addEventListener('click', function() { highlightCord('ant'); });
    if (selLat) selLat.addEventListener('click', function() { highlightCord('lat'); });
    if (selPos) selPos.addEventListener('click', function() { highlightCord('pos'); });

    // Direct Cord Targets
    ['a12p20h-axial-cord-ant', 'a12p20h-sag-cord-ant'].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.addEventListener('click', function() { highlightCord('ant'); });
    });

    ['a12p20h-axial-cord-lat', 'a12p20h-sag-cord-lat'].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.addEventListener('click', function() { highlightCord('lat'); });
    });

    ['a12p20h-axial-cord-pos', 'a12p20h-sag-cord-pos'].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.addEventListener('click', function() { highlightCord('pos'); });
    });

    // Tabs
    var tabDual = document.getElementById('a12p20h-tab-dual');
    var tabAxial = document.getElementById('a12p20h-tab-axial');
    var tabSagittal = document.getElementById('a12p20h-tab-sagittal');

    if (tabDual) tabDual.addEventListener('click', function() { switchView('dual'); });
    if (tabAxial) tabAxial.addEventListener('click', function() { switchView('axial'); });
    if (tabSagittal) tabSagittal.addEventListener('click', function() { switchView('sagittal'); });

    // Cards
    var cardSuspensa = document.getElementById('a12p20h-card-suspensa');
    var cardSustenta = document.getElementById('a12p20h-card-sustenta');

    if (cardSuspensa) cardSuspensa.addEventListener('click', function() { highlightCord('all'); });
    if (cardSustenta) cardSustenta.addEventListener('click', function() { highlightCord('sustentacao'); });
  });
})();
